inline std::string Hex(const std::vector<std::uint8_t>& bytes)
{
  static constexpr char digits[] = "0123456789abcdef";
  std::string out;
  for (const std::uint8_t b : bytes)
  {
    out += digits[b >> 4];
    out += digits[b & 15];
  }
  return out;
}

inline std::string Describe(const Ping& p)
{
  return std::string("Ping") + " Nonce=" + std::to_string(p.nonce) + " ClientTicks=" + std::to_string(p.client_ticks) + " Token=" + (p.token ? std::to_string(*p.token) : std::string("-"));
}

